"""Verify generated summary references against original committed source markers.

This is a structural citation/provenance gate, NOT factual entailment
verification. Reviewers must still inspect any summary before approval.
"""
from __future__ import annotations

import re

# Segment IDs generated by the live service are alphanumeric/ASCII with a
# small delimiter set. Do not permit free-form quoted text as an ID, because
# bracket injection would make source markers ambiguous.
_MARKER = r"\[([A-Za-z0-9][A-Za-z0-9_.:-]{0,127}) at (\d{1,7})s\]"
_SOURCE = re.compile(r"^" + _MARKER + r"(?=\s)")
_REFERENCE = re.compile(_MARKER)
_SUSPICIOUS = re.compile(r"\[[^\]\r\n]{0,160}\s+at\s+\d+s\]")


def allowed_source_citations(source: str) -> set[str]:
    """Read canonical marker syntax from the immutable summarized source."""
    if not source or len(source) > 240_000:
        raise ValueError("missing or oversized source transcript")
    citations: set[str] = set()
    segment_ids: set[str] = set()
    for line in source.splitlines():
        if not line.startswith("["):
            continue  # A transcript can contain newlines inside spoken text.
        match = _SOURCE.match(line)
        if match is None:
            raise ValueError("unsafe or invalid transcript citation marker")
        segment_id = match.group(1)
        if segment_id in segment_ids:
            raise ValueError("duplicate source segment ID is ambiguous")
        segment_ids.add(segment_id)
        citations.add(match.group(0))
    if not citations:
        raise ValueError("source has no valid segment citations")
    return citations


def validate_summary_citations(source: str, summary: str) -> list[str]:
    """Require cited source segments and reject unknown/mismatched timecodes.

    Exact citations MUST appear as [segment-id at 123s]. A quoted invented
    identifier or altered timestamp never gets to count as grounded.
    This cannot verify semantic entailment or missing citations within prose.
    """
    allowed = allowed_source_citations(source)
    if not isinstance(summary, str) or not summary.strip():
        raise ValueError("summary has no content")
    if len(summary) > 15_000:
        raise ValueError("summary exceeds output limit")
    references = list(_REFERENCE.finditer(summary))
    if not references:
        raise ValueError("summary must cite at least one original segment")
    for match in references:
        if match.group(0) not in allowed:
            raise ValueError("summary cites an unknown segment or mismatched timestamp")
    # Detect other bracketed 'at Ns' claims which would bypass the strict
    # validator because of malformed punctuation / unexpected ID characters.
    for candidate in _SUSPICIOUS.finditer(summary):
        if _REFERENCE.fullmatch(candidate.group(0)) is None:
            raise ValueError("summary contains malformed segment citation")
    return list(dict.fromkeys(match.group(0) for match in references))
